import numpy as np
J=np.load('/app/output/visual_jacobian.npy');
for d in [[-.055,-.068,-.1]]:
 for lam in [0,.005,.01,.02]:
  dq=J.T@np.linalg.solve(J@J.T+lam**2*np.eye(3),d)
  print(lam,np.round(dq,3),np.round(J@dq,3),np.linalg.norm(dq))
